from pathlib import Path
from playwright.sync_api import sync_playwright
import json
B=Path(__file__).parent;out=[]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage']);pg=b.new_page(viewport={'width':1400,'height':1000})
 for mode in ['light','dark']:
  pg.goto('http://127.0.0.1:8765/current-fold-review/library/'+mode+'.html');pg.evaluate('document.fonts.ready')
  vals=pg.evaluate('''()=>{const cv=document.createElement('canvas');cv.width=cv.height=1;let ctx=cv.getContext('2d');function rgba(c){ctx.clearRect(0,0,1,1);ctx.fillStyle=c;ctx.fillRect(0,0,1,1);return [...ctx.getImageData(0,0,1,1).data]}function lum(c){let a=c.slice(0,3).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4});return .2126*a[0]+.7152*a[1]+.0722*a[2]}let contrast=[],chips=[],count=0;document.querySelectorAll('article').forEach(a=>{let label=a.querySelector('h2').textContent;[...a.querySelectorAll('.slide .name,.slide .note,.slide .fig,.slide .kick,.slide p,.slide td,.slide th')].forEach(e=>{let s=getComputedStyle(e),r=e.getBoundingClientRect();if(!r.width||!r.height||s.display==='none'||!e.textContent.trim())return;let bg=[255,255,255,255],chain=[];for(let z=e;z;z=z.parentElement)chain.push(z);chain.reverse().forEach(z=>{let c=rgba(getComputedStyle(z).backgroundColor),al=c[3]/255;bg=bg.map((v,i)=>i<3?v*(1-al)+c[i]*al:255)});let fg=rgba(s.color),l1=lum(fg),l2=lum(bg),ratio=(Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05),min=parseFloat(s.fontSize)>=28?3:4.5;count++;if(ratio<min-.03)contrast.push({fixture:label,text:e.textContent.slice(0,60),ratio:Math.round(ratio*100)/100,min});});[...a.querySelectorAll('.slide .pill,.slide .chip,.slide .tag,.slide .card .mark,.slide .steps .mark,.slide .pill .mark')].forEach(e=>{if(e.querySelector('.icon')||e.querySelector('[data-ph]')||!e.textContent.trim())return;let s=getComputedStyle(e);if(s.display==='none')return;let range=document.createRange();range.selectNodeContents(e);let t=range.getBoundingClientRect(),r=e.getBoundingClientRect();if(!t.width||!r.width||t.height>50)return;let dx=(t.left+t.right-r.left-r.right)/2,dy=(t.top+t.bottom-r.top-r.bottom)/2;if(Math.abs(dx)>5||Math.abs(dy)>6)chips.push({fixture:label,text:e.textContent.slice(0,50),dx:Math.round(dx),dy:Math.round(dy)});});});return{mode:'',textCount:count,contrastFailures:contrast,chipCenterWarnings:chips}}''');vals['mode']=mode;out.append(vals)
 b.close()
(B/'contrast-chip-audit.json').write_text(json.dumps(out,ensure_ascii=False,indent=2));print([(v['mode'],v['textCount'],len(v['contrastFailures']),len(v['chipCenterWarnings'])) for v in out])
